config.initialQuery:
/* Traverse the graph by copying a vertex _id into the start position:
   FOR v, e, p IN 1..2 ANY "collection/key" GRAPH `${resource.name}` LIMIT 25 RETURN p */
FOR g IN _graphs
  FILTER g._key == "${resource.name}"
  FOR def IN g.edgeDefinitions
    RETURN { edge: def.collection, from: def.from, to: def.to, edges: COLLECTION_COUNT(def.collection) }
